-- Alpha block id (+meta) <-> VoxelCore block index. Table: modules/blocks_table.lua (GENERATED by
-- tools/alphamine/gen_pack_blocks.py from D:\Prog\AlphaMine\tables\blocks.json).
-- Every Alpha block is its own VoxelCore block `alphamine:<name_snake>`; the Alpha meta goes into the
-- userbits of the state (state = meta << 8), blocks with meta-dependent textures pick a state-based
-- variant by it. So engine block -> (alpha id, meta) is exact: id = to_alpha[index], meta = state >> 8.
local T = require "alphamine:blocks_table"

local M = {
    table = T,
    to_vc = {},     -- [0..255] alpha id -> VoxelCore block index (0 = core:air for unknown ids)
    to_alpha = {},  -- VoxelCore block index -> alpha id (nil for blocks of other packs)
    box = {},       -- [alpha id] -> collision box {x0,y0,z0,x1,y1,z1} (nil = no collision)
    unknown = {},   -- alpha ids that came from the server but are not in the table (-> air), count
    ready = false,
}

function M.init()
    if M.ready then return end
    for i = 0, 255 do M.to_vc[i] = 0 end
    M.to_alpha[0] = 0
    for id, e in pairs(T) do
        local idx = block.index("alphamine:" .. e.name)
        M.to_vc[id] = idx
        M.to_alpha[idx] = id
        M.box[id] = e.box
    end
    M.ready = true
end

function M.vc_state(meta)
    return meta * 256
end

-- engine voxel at world coords -> alpha id, meta (id -1 when the engine has no chunk there)
function M.alpha_at(x, y, z)
    local idx = block.get(x, y, z)
    if idx == nil or idx < 0 then return -1, 0 end
    local id = M.to_alpha[idx]
    if id == nil then return -2, 0 end
    local st = block.get_states(x, y, z) or 0
    return id, math.floor(st / 256) % 16
end

return M
